const $ = (id) => document.getElementById(id);
const sources = {
  versailles:'https://en.chateauversailles.fr/discover/history/key-dates/versailles-heart-french-revolution',
  oath:'https://en.chateauversailles.fr/discover/history/key-dates/jeu-paume-oath-1789',
  bastille:'https://www.elysee.fr/la-presidence/la-fete-nationale-du-14-juillet',
  rights:'https://www.elysee.fr/la-presidence/les-textes-fondateurs',
  march:'https://en.chateauversailles.fr/discover/history/key-dates/departure-king-1789',
  overview:'https://en.wikipedia.org/wiki/French_Revolution',
  terror:'https://en.wikipedia.org/wiki/Reign_of_Terror',
  napoleon:'https://www.napoleon.org/en/history-of-the-two-empires/close-up/the-coup-detat-of-18-and-19-brumaire-an-viii-9-and-10-november1799'
};
// Dates and explanatory diagrams are deliberately separate: timeline intervals are not to scale.
const events = [
 {year:'1789',source:'versailles',kind:'estates',en:{short:'A nation in crisis',phase:'ACT I · THE OLD ORDER CRACKS',date:'5 May 1789 · Versailles',title:'One nation.<br>Three unequal voices.',description:'The crown is deep in debt. Bread is expensive. Louis XVI calls the Estates-General: clergy, nobles and the Third Estate. The Third Estate represents most people, but voting by estate could let the other two outvote it.',why:'A financial crisis becomes a question of political power: who has the right to speak for France?'},fr:{short:'Une nation en crise',phase:'ACTE I · L’ORDRE ANCIEN SE FISSURE',date:'5 mai 1789 · Versailles',title:'Une nation.<br>Trois voix inégales.',description:'La monarchie est endettée et le pain coûte cher. Louis XVI réunit les États généraux : clergé, noblesse et tiers état. Ce dernier représente la majorité des Français, mais le vote par ordre permet aux deux autres de le mettre en minorité.',why:'La crise financière devient une question politique : qui a le droit de parler au nom de la France ?'}},
 {year:'1789',source:'oath',kind:'oath',en:{short:'The oath',phase:'ACT I · THE OLD ORDER CRACKS',date:'20 June 1789 · Versailles',title:'A promise the king<br>cannot silence.',description:'After declaring themselves the National Assembly, deputies gather in an indoor tennis court. They swear not to separate until France has a constitution: rules that would limit royal power.',why:'Representatives claim that political authority belongs to the nation, challenging the king’s claim to rule.'},fr:{short:'Le serment',phase:'ACTE I · L’ORDRE ANCIEN SE FISSURE',date:'20 juin 1789 · Versailles',title:'Un serment que le roi<br>ne peut faire taire.',description:'Après s’être proclamés Assemblée nationale, des députés se réunissent dans une salle de jeu de paume. Ils jurent de ne pas se séparer avant d’avoir donné une constitution à la France : des règles pour encadrer le pouvoir royal.',why:'Les représentants affirment que l’autorité politique appartient à la nation, contestant le pouvoir du roi.'}},
 {year:'1789',source:'bastille',kind:'bastille',en:{short:'The Bastille',phase:'ACT II · THE PEOPLE ENTER HISTORY',date:'14 July 1789 · Paris',title:'A fortress falls.<br>A symbol rises.',description:'Parisians fear royal troops will crush the new Assembly. Searching for gunpowder, an armed crowd storms the Bastille, a fortress and prison associated with royal authority.',why:'Popular action helps defend the revolution. The fall of the Bastille becomes its most enduring symbol.'},fr:{short:'La Bastille',phase:'ACTE II · LE PEUPLE ENTRE DANS L’HISTOIRE',date:'14 juillet 1789 · Paris',title:'Une forteresse tombe.<br>Un symbole naît.',description:'Les Parisiens craignent que les troupes royales n’écrasent la nouvelle Assemblée. À la recherche de poudre, une foule armée prend la Bastille, forteresse et prison associée à l’autorité royale.',why:'L’action populaire contribue à défendre la Révolution. La chute de la Bastille en devient le symbole le plus durable.'}},
 {year:'1789',source:'rights',kind:'rights',en:{short:'Rights declared',phase:'ACT II · THE PEOPLE ENTER HISTORY',date:'August 1789 · Versailles',title:'Privilege gives way<br>to rights.',description:'On 4 August, the Assembly begins dismantling feudal privileges. On 26 August, it adopts the Declaration of the Rights of Man and of the Citizen, proclaiming liberty and equality before the law.',why:'Rights replace inherited rank as a new ideal. But women are excluded from equal political rights, and slavery continues in the colonies.'},fr:{short:'Les droits proclamés',phase:'ACTE II · LE PEUPLE ENTRE DANS L’HISTOIRE',date:'Août 1789 · Versailles',title:'Des privilèges<br>aux droits.',description:'Le 4 août, l’Assemblée entreprend d’abolir les privilèges féodaux. Le 26 août, elle adopte la Déclaration des droits de l’homme et du citoyen, proclamant la liberté et l’égalité devant la loi.',why:'Les droits deviennent un idéal face aux privilèges de naissance. Mais les femmes restent exclues de l’égalité politique et l’esclavage continue dans les colonies.'}},
 {year:'1789',source:'march',kind:'march',en:{short:'Women march',phase:'ACT II · THE PEOPLE ENTER HISTORY',date:'5–6 October 1789 · Paris → Versailles',title:'Bread. A march.<br>A king brought back.',description:'A crowd led by women marches from Paris to Versailles, demanding bread and action. The next day, the royal family is brought to Paris, closer to the people and the Assembly.',why:'Women shape the revolution even without voting rights. The centre of royal power shifts from Versailles to Paris.'},fr:{short:'La marche des femmes',phase:'ACTE II · LE PEUPLE ENTRE DANS L’HISTOIRE',date:'5–6 octobre 1789 · Paris → Versailles',title:'Du pain. Une marche.<br>Le roi ramené à Paris.',description:'Une foule menée par des femmes marche de Paris à Versailles pour réclamer du pain et des mesures concrètes. Le lendemain, la famille royale est ramenée à Paris, plus près du peuple et de l’Assemblée.',why:'Les femmes font la Révolution sans avoir le droit de vote. Le centre du pouvoir royal passe de Versailles à Paris.'}},
 {year:'1791',source:'overview',kind:'constitution',en:{short:'Trust breaks',phase:'ACT III · THE REVOLUTION RADICALISES',date:'June–September 1791 · France',title:'A king with limits.<br>A nation without trust.',description:'Louis XVI’s attempted escape ends at Varennes in June, damaging trust in him. In September, a constitution establishes a constitutional monarchy: the king remains, but his power is limited. Voting rights depend on sex and tax qualifications.',why:'Compromise still seems possible, but suspicion of the king makes the new political system fragile.'},fr:{short:'La confiance brisée',phase:'ACTE III · LA RÉVOLUTION SE RADICALISE',date:'Juin–septembre 1791 · France',title:'Un roi limité.<br>Une confiance brisée.',description:'En juin, la fuite de Louis XVI est arrêtée à Varennes, ce qui ébranle la confiance envers lui. En septembre, une constitution instaure une monarchie constitutionnelle : le roi reste, mais son pouvoir est limité. Le vote dépend du sexe et du cens.',why:'Un compromis semble encore possible, mais la méfiance envers le roi fragilise le nouveau régime.'}},
 {year:'1792',source:'overview',kind:'republic',en:{short:'The republic',phase:'ACT III · THE REVOLUTION RADICALISES',date:'1792–1793 · Paris',title:'No more king.<br>A republic is born.',description:'War and fear of betrayal fuel the uprising of 10 August 1792, which topples royal authority. On 21 September, the Convention abolishes the monarchy. Louis XVI is tried and executed on 21 January 1793.',why:'France becomes a republic. War abroad and division at home make its future deeply uncertain.'},fr:{short:'La République',phase:'ACTE III · LA RÉVOLUTION SE RADICALISE',date:'1792–1793 · Paris',title:'Plus de roi.<br>La République naît.',description:'La guerre et la peur de la trahison nourrissent l’insurrection du 10 août 1792, qui renverse le pouvoir royal. Le 21 septembre, la Convention abolit la monarchie. Louis XVI est jugé puis exécuté le 21 janvier 1793.',why:'La France devient une république. La guerre extérieure et les divisions intérieures rendent son avenir incertain.'}},
 {year:'1793–94',source:'terror',kind:'terror',en:{short:'The Terror',phase:'ACT IV · LIBERTY UNDER PRESSURE',date:'1793–1794 · France',title:'Defending liberty.<br>Destroying freedoms.',description:'Facing invasion and internal revolt, revolutionary leaders use emergency government, arrests and executions against suspected enemies. The Committee of Public Safety becomes a powerful centre of government. Robespierre falls in July 1794.',why:'The Terror exposes a central contradiction: can a government defend freedom by taking it away?'},fr:{short:'La Terreur',phase:'ACTE IV · LA LIBERTÉ SOUS PRESSION',date:'1793–1794 · France',title:'Défendre la liberté.<br>Supprimer des libertés.',description:'Face à l’invasion et aux révoltes intérieures, les dirigeants révolutionnaires recourent au gouvernement d’exception, aux arrestations et aux exécutions. Le Comité de salut public devient un centre majeur du pouvoir. Robespierre tombe en juillet 1794.',why:'La Terreur révèle une contradiction : un gouvernement peut-il défendre la liberté en la supprimant ?'}},
 {year:'1795',source:'overview',kind:'directory',en:{short:'The Directory',phase:'ACT IV · LIBERTY UNDER PRESSURE',date:'1795–1799 · France',title:'Five directors.<br>An unstable republic.',description:'A new constitution creates the Directory: five executive directors and two legislative chambers. It seeks stability after the Terror, but struggles with economic hardship, political opposition and repeated coups.',why:'The government depends increasingly on the army. Successful generals gain influence as civilian authority weakens.'},fr:{short:'Le Directoire',phase:'ACTE IV · LA LIBERTÉ SOUS PRESSION',date:'1795–1799 · France',title:'Cinq directeurs.<br>Une république fragile.',description:'Une nouvelle constitution crée le Directoire : cinq directeurs exercent le pouvoir exécutif face à deux chambres législatives. Le régime cherche la stabilité après la Terreur, mais affronte difficultés économiques, oppositions et coups d’État.',why:'Le gouvernement dépend de plus en plus de l’armée. Les généraux victorieux gagnent en influence tandis que le pouvoir civil s’affaiblit.'}},
 {year:'1799',source:'napoleon',kind:'napoleon',en:{short:'Napoleon’s coup',phase:'ACT V · A NEW KIND OF POWER',date:'9–10 November 1799 · Saint-Cloud & Paris',title:'The revolution ends.<br>Its legacy does not.',description:'Napoleon Bonaparte and his allies overthrow the Directory in the coup of 18–19 Brumaire. The Consulate replaces it, with Napoleon as First Consul. This is conventionally treated as the end of the French Revolution.',why:'Power concentrates in one leader. Some revolutionary changes endure, while political liberty narrows. Napoleon becomes emperor in 1804, not 1799.'},fr:{short:'Le coup de Bonaparte',phase:'ACTE V · UNE AUTRE FORME DE POUVOIR',date:'9–10 novembre 1799 · Saint-Cloud et Paris',title:'La Révolution s’achève.<br>Son héritage demeure.',description:'Napoléon Bonaparte et ses alliés renversent le Directoire lors du coup d’État des 18 et 19 Brumaire. Le Consulat le remplace, avec Bonaparte comme Premier consul. Cet événement marque traditionnellement la fin de la Révolution française.',why:'Le pouvoir se concentre dans les mains d’un dirigeant. Certains acquis subsistent, mais la liberté politique recule. Napoléon devient empereur en 1804, pas en 1799.'}}
];
const ui = {
 en:{timeline:'The timeline',legacy:'The legacy',sources:'Sources',eyebrow:'FRANCE, 1789. EVERYTHING IS ABOUT TO CHANGE.',heroTitle:'A world turned<br><em>upside down.</em>',heroCopy:'A king. A restless nation. A revolution that reshaped the world. Step into the decade when ordinary people changed history.',explore:'Explore the revolution',five:'◷　A 5-minute journey',ten:'10 defining moments',painting:'The Storming of the Bastille',scroll:'SCROLL TO DISCOVER',chapterLabel:'THE REVOLUTION, MOMENT BY MOMENT',journeyTitle:'Ten years. A new world.',journeyHint:'Choose any moment. Follow the turning points.<br>See how one event leads to the next.',keys:' · Use ← → to explore',why:'WHY IT MATTERS',readSource:'Read the historical source',free:'Explore in any order',echo:'THE ECHO OF A REVOLUTION',legacyTitle:'The monarchy fell.<br>The questions remained.',legacyCopy:'Who holds power? Who gets a voice? What does equality really mean? The revolution did not settle these questions. It made them impossible to ignore.',liberty:'Liberty',libertyCopy:'Freedom from arbitrary rule became a powerful ideal. Yet revolutionary governments also imprisoned and executed their opponents.',equality:'Equality',equalityCopy:'Inherited privileges were challenged. But women lacked equal political rights, and colonial slavery exposed the limits of universal promises.',sovereignty:'Popular sovereignty',sovereigntyCopy:'Authority could come from the nation rather than a royal bloodline. Napoleon’s rise showed how fragile that principle could be.',footer:'A short journey through a complicated history.',back:'Back to the beginning ↑',sourcesTitle:'Sources & further exploration',sourceIntro:'A simplified introduction for students. The timeline spaces events equally for navigation, not in proportion to elapsed time. Diagrams are explanatory schematics, not measured data.',artwork:'Artwork',artNote:'The painting introduces the period; it is not a depiction of every event in the timeline. The familiar three-part French motto developed over time.'},
 fr:{timeline:'La chronologie',legacy:'L’héritage',sources:'Sources',eyebrow:'FRANCE, 1789. TOUT EST SUR LE POINT DE CHANGER.',heroTitle:'Un monde<br><em>bouleversé.</em>',heroCopy:'Un roi. Une nation en ébullition. Une révolution qui transforme le monde. Découvrez la décennie où des gens ordinaires ont changé l’histoire.',explore:'Explorer la Révolution',five:'◷　Un voyage de 5 minutes',ten:'10 moments décisifs',painting:'La Prise de la Bastille',scroll:'DÉFILER POUR DÉCOUVRIR',chapterLabel:'LA RÉVOLUTION, MOMENT PAR MOMENT',journeyTitle:'Dix ans. Un monde nouveau.',journeyHint:'Choisissez un moment. Explorez les tournants.<br>Découvrez comment les événements s’enchaînent.',keys:' · Explorez avec ← →',why:'POURQUOI C’EST IMPORTANT',readSource:'Consulter la source historique',free:'Explorez dans l’ordre de votre choix',echo:'L’ÉCHO D’UNE RÉVOLUTION',legacyTitle:'La monarchie est tombée.<br>Les questions demeurent.',legacyCopy:'Qui détient le pouvoir ? Qui peut se faire entendre ? Que signifie vraiment l’égalité ? La Révolution n’a pas résolu ces questions. Elle les a rendues incontournables.',liberty:'Liberté',libertyCopy:'La liberté face à l’arbitraire devient un idéal puissant. Pourtant, les gouvernements révolutionnaires emprisonnent et exécutent aussi leurs opposants.',equality:'Égalité',equalityCopy:'Les privilèges de naissance sont contestés. Mais les femmes n’ont pas les mêmes droits politiques, et l’esclavage colonial révèle les limites des promesses universelles.',sovereignty:'Souveraineté nationale',sovereigntyCopy:'L’autorité peut venir de la nation plutôt que d’une lignée royale. L’ascension de Napoléon montre la fragilité de ce principe.',footer:'Un court voyage dans une histoire complexe.',back:'Revenir au début ↑',sourcesTitle:'Sources et pistes pour aller plus loin',sourceIntro:'Une introduction simplifiée pour les élèves. Les événements sont espacés régulièrement pour faciliter la navigation, sans représenter la durée réelle. Les schémas sont explicatifs : ils ne représentent pas des données mesurées.',artwork:'Œuvre',artNote:'Le tableau introduit la période : il ne représente pas chacun des événements. La devise française en trois mots s’est construite progressivement.'}
};
let lang='en', index=0;
const visited=new Set([0]);
const tr=(en,fr)=>lang==='en'?en:fr;
const note=(text)=>`<p class="visual-note">${text}</p>`;
const tag=(text)=>`<div class="visual-tag">${text}</div>`;
function power(left,right,ln,rn){return `<div class="power"><div class="power-node"><strong>${left}</strong>${ln}</div><span class="power-arrow" aria-hidden="true">→</span><div class="power-node"><strong>${right}</strong>${rn}</div></div>`;}
function visual(kind){
 switch(kind){
 case 'estates':return tag(tr('THE QUESTION OF REPRESENTATION','LA QUESTION DE LA REPRÉSENTATION'))+`<h4>${tr('Who gets a voice?','Qui peut se faire entendre ?')}</h4><div id="estate-rows"></div><button id="vote-switch" aria-pressed="false">${tr('Compare votes by head ↗','Comparer le vote par tête ↗')}</button><p id="vote-note" class="visual-note"></p>`;
 case 'oath':return tag(tr('A NEW SOURCE OF AUTHORITY','UNE NOUVELLE SOURCE D’AUTORITÉ'))+`<div class="oath"><span>1789</span><small>${tr('A constitution.<br>Limits on the king.<br>Authority from the nation.','Une constitution.<br>Un pouvoir royal encadré.<br>L’autorité vient de la nation.')}</small><div class="signature"></div></div>`+note(tr('The oath is a promise to write a constitution, not yet the abolition of monarchy.','Le serment promet une constitution : il n’abolit pas encore la monarchie.'));
 case 'bastille':return tag(tr('THE POWER OF A SYMBOL','LA FORCE D’UN SYMBOLE'))+`<div class="fortress" id="fortress" role="img" aria-label="${tr('Schematic of the Bastille fortress','Schéma de la forteresse de la Bastille')}"><i></i><i></i><i></i></div><h4>${tr('Royal authority challenged','Le pouvoir royal défié')}</h4><button id="bastille-action" aria-pressed="false">${tr('See what changed ↗','Voir ce qui change ↗')}</button><p class="visual-note" id="bastille-note">${tr('The prison holds only seven prisoners. Its political meaning is much larger.','La prison ne compte que sept prisonniers. Sa portée politique est bien plus grande.')}</p>`;
 case 'rights':return tag(tr('26 AUGUST 1789','26 AOÛT 1789'))+`<div class="rights"><div class="right-line"><span>01</span>${tr('Liberty','Liberté')}</div><div class="right-line"><span>02</span>${tr('Equality before the law','Égalité devant la loi')}</div><div class="right-line"><span>03</span>${tr('National sovereignty','Souveraineté nationale')}</div></div>`+note(tr('A universal promise. Unequal access to political rights.','Une promesse universelle. Un accès inégal aux droits politiques.'));
 case 'march':return tag(tr('A JOURNEY THAT MOVED POWER','UNE MARCHE QUI DÉPLACE LE POUVOIR'))+`<h4>${tr('From the streets to the palace','De la rue au palais')}</h4><div class="route" id="route"><div class="route-place"><b></b>Paris</div><span class="marcher" aria-hidden="true">→</span><div class="route-place"><b></b>Versailles</div></div><button id="march-action" aria-pressed="false">${tr('6 October: follow the king’s return ↗','6 octobre : suivre le retour du roi ↗')}</button><p class="visual-note" id="march-note">${tr('5 October: marchers demand bread at Versailles. Schematic, not a map.','5 octobre : la foule réclame du pain à Versailles. Schéma, pas une carte.')}</p>`;
 case 'constitution':return tag(tr('CONSTITUTIONAL MONARCHY','MONARCHIE CONSTITUTIONNELLE'))+power('R','L',tr('The king','Le roi'),tr('The law','La loi'))+`<div class="balance equal" role="img" aria-label="${tr('Scales illustrating legal limits on royal power','Balance symbolisant les limites juridiques du pouvoir royal')}"><div class="post"></div><div class="beam"></div></div>`+note(tr('The crown survives, but it must operate within a constitution. Equal citizenship is still incomplete.','La couronne subsiste, mais elle doit respecter une constitution. L’égalité citoyenne reste incomplète.'));
 case 'republic':return tag(tr('21 SEPTEMBER 1792','21 SEPTEMBRE 1792'))+power('♔','R',tr('Monarchy','Monarchie'),tr('Republic','République'))+`<h4>${tr('From subjects to citizens','De sujets à citoyens')}</h4>`+note(tr('A republic has no hereditary monarch. Becoming one does not guarantee peace or equal rights for everyone.','Une république n’a pas de monarque héréditaire. Elle ne garantit pas à elle seule la paix ni l’égalité pour tous.'));
 case 'terror':return tag(tr('AN EMERGENCY GOVERNMENT','UN GOUVERNEMENT D’EXCEPTION'))+`<h4>${tr('Security and freedom','Sécurité et liberté')}</h4><div class="balance" id="terror-balance" role="img" aria-label="${tr('An unbalanced scale symbolising tension between emergency powers and liberties','Une balance inclinée symbolisant la tension entre pouvoirs d’exception et libertés')}"><div class="post"></div><div class="beam"></div></div>`+note(tr('War and revolt → emergency powers → repression.<br>This is a chain of decisions, not an inevitable outcome.','Guerre et révoltes → pouvoirs d’exception → répression.<br>Une suite de décisions, pas une issue inévitable.'));
 case 'directory':return tag(tr('EXECUTIVE POWER SHARED FIVE WAYS','LE POUVOIR EXÉCUTIF PARTAGÉ À CINQ'))+`<div class="directors" role="img" aria-label="${tr('Five directors','Cinq directeurs')}">${'<i></i>'.repeat(5)}</div><h4>${tr('Sharing power ≠ stability','Partager le pouvoir ≠ la stabilité')}</h4>`+note(tr('Two legislative chambers. Five directors.<br>A government increasingly reliant on the army.','Deux chambres législatives. Cinq directeurs.<br>Un gouvernement toujours plus dépendant de l’armée.'));
 case 'napoleon':return tag(tr('FROM THE DIRECTORY TO THE CONSULATE','DU DIRECTOIRE AU CONSULAT'))+power('5','1',tr('Directors','Directeurs'),tr('Dominant First Consul','Premier consul dominant'))+`<h4>${tr('A concentration of power','Un pouvoir concentré')}</h4>`+note(tr('Three consuls formally govern. Napoleon, the First Consul, dominates. The Empire comes later, in 1804.','Trois consuls gouvernent officiellement. Bonaparte, Premier consul, domine. L’Empire vient ensuite, en 1804.'));
 }
}
function setupVisual(){
 if(events[index].kind==='estates'){
   const update=(heads)=>{
     const names=tr(['Clergy','Nobility','Third Estate'],['Clergé','Noblesse','Tiers état']);
     $('estate-rows').innerHTML=names.map((n,i)=>`<div class="estate-row"><span>${n}</span><span class="estate-votes" aria-label="${heads?tr('Illustrative size of delegation','Taille indicative de la délégation'):tr('One vote','Une voix')}">${'<i></i>'.repeat(heads?(i===2?12:6):1)}</span></div>`).join('');
     $('vote-note').textContent=heads?tr('Illustration: the Third Estate has about as many deputies as the other two combined. Deputies from the other estates can join it.','Illustration : le tiers état compte environ autant de députés que les deux autres ordres réunis. Des députés des autres ordres peuvent le rejoindre.'):tr('Voting by estate: one vote for each order. Two orders can outvote the Third Estate.','Vote par ordre : chaque ordre a une voix. Deux ordres peuvent mettre le tiers état en minorité.');
     $('vote-switch').setAttribute('aria-pressed',String(heads));
     $('vote-switch').textContent=heads?tr('Return to votes by estate ↶','Revenir au vote par ordre ↶'):tr('Compare votes by head ↗','Comparer le vote par tête ↗');
   };update(false);$('vote-switch').onclick=()=>update($('vote-switch').getAttribute('aria-pressed')!=='true');
 }
 if($('bastille-action'))$('bastille-action').onclick=()=>{const active=$('bastille-action').getAttribute('aria-pressed')!=='true';$('fortress').classList.toggle('open',active);$('bastille-action').setAttribute('aria-pressed',String(active));$('bastille-note').textContent=active?tr('The crowd’s victory shows that royal power can be resisted. The fortress is dismantled in the months that follow.','La victoire de la foule montre qu’on peut résister au pouvoir royal. La forteresse est démantelée au cours des mois suivants.'):tr('The prison holds only seven prisoners. Its political meaning is much larger.','La prison ne compte que sept prisonniers. Sa portée politique est bien plus grande.');};
 if($('march-action'))$('march-action').onclick=()=>{const active=$('march-action').getAttribute('aria-pressed')!=='true';$('route').classList.toggle('returning',active);$('route').querySelector('.marcher').textContent=active?'←':'→';$('march-action').setAttribute('aria-pressed',String(active));$('march-note').textContent=active?tr('6 October: the royal family moves to Paris. The king is now much closer to popular pressure.','6 octobre : la famille royale rejoint Paris. Le roi est désormais beaucoup plus exposé à la pression populaire.'):tr('5 October: marchers demand bread at Versailles. Schematic, not a map.','5 octobre : la foule réclame du pain à Versailles. Schéma, pas une carte.');};
}
function render(animate=true){
 const event=events[index],e=event[lang];
 $('timeline').innerHTML=events.map((v,i)=>`<button type="button" data-event="${i}" aria-current="${i===index}" aria-label="${v[lang].date}: ${v[lang].short}"><span class="tl-year">${v.year}</span><span class="tl-dot"></span><span class="tl-name">${v[lang].short}</span></button>`).join('');
 $('phase').textContent=e.phase;$('date').textContent=e.date;$('event-title').innerHTML=e.title;$('description').textContent=e.description;$('consequence').textContent=e.why;$('count').textContent=String(index+1).padStart(2,'0');$('event-source').href=sources[event.source];$('visual').innerHTML=visual(event.kind);
 $('prev').disabled=index===0;$('next').disabled=index===events.length-1;
 $('prev').setAttribute('aria-label',tr('Previous event','Événement précédent'));$('next').setAttribute('aria-label',tr('Next event','Événement suivant'));
 $('visited').textContent=tr(`${visited.size} of 10 moments explored`,`${visited.size} moments explorés sur 10`);$('visited-fill').style.width=`${visited.size*10}%`;
 if(animate){$('chapter').classList.remove('enter');void $('chapter').offsetWidth;$('chapter').classList.add('enter');}
 setupVisual();
}
function select(i){if(i<0||i>=events.length)return;index=i;visited.add(i);render();const active=$('timeline').querySelector('[aria-current="true"]');const box=$('timeline').parentElement;box.scrollTo({left:Math.max(0,active.offsetLeft-box.clientWidth/2+active.clientWidth/2),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
function setLanguage(l){lang=l;document.documentElement.lang=lang;document.querySelectorAll('[data-i]').forEach(n=>{n.innerHTML=ui[lang][n.dataset.i]||n.innerHTML;});$('en').setAttribute('aria-pressed',String(lang==='en'));$('fr').setAttribute('aria-pressed',String(lang==='fr'));document.querySelector('.skip').textContent=tr('Skip to the timeline','Aller à la chronologie');document.querySelector('.languages').setAttribute('aria-label',tr('Language','Langue'));$('sources-close').setAttribute('aria-label',tr('Close sources','Fermer les sources'));document.querySelector('.hero-art').setAttribute('aria-label',tr('The Storming of the Bastille, a painting by Jean-Pierre Houël, 1789','La Prise de la Bastille, tableau de Jean-Pierre Houël, 1789'));render(false);}
 $('timeline').addEventListener('click',e=>{const b=e.target.closest('[data-event]');if(b)select(Number(b.dataset.event));});
 $('prev').onclick=()=>select(index-1);$('next').onclick=()=>select(index+1);$('en').onclick=()=>setLanguage('en');$('fr').onclick=()=>setLanguage('fr');
 document.addEventListener('keydown',e=>{if($('sources-dialog').open||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||!e.target.closest('#journey'))return;if(e.key==='ArrowRight'){e.preventDefault();select(index+1);$('timeline').querySelector('[aria-current="true"]').focus({preventScroll:true});}if(e.key==='ArrowLeft'){e.preventDefault();select(index-1);$('timeline').querySelector('[aria-current="true"]').focus({preventScroll:true});}});
 $('sources-open').onclick=$('sources-footer').onclick=()=>$('sources-dialog').showModal();$('sources-close').onclick=()=>$('sources-dialog').close();$('sources-dialog').addEventListener('click',e=>{if(e.target===$('sources-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
 render(false);
